CREATE TABLE `ns_blindbox` (
  `blindbox_id` int(11) UNSIGNED NOT NULL,
  `category_id` int(11) NOT NULL DEFAULT 0 COMMENT '分类Id',
  `blindbox_name` varchar(128) NOT NULL DEFAULT '' COMMENT '盲盒名称',
  `goods_ids` varchar(128) NOT NULL DEFAULT '' COMMENT '商品组',
  `blindbox_images` varchar(255) NOT NULL DEFAULT '' COMMENT '盲盒封面',
  `blindbox_count` int(11) NOT NULL DEFAULT 0 COMMENT '盲盒放置总量',
  `blindbox_inventory` int(11) NOT NULL DEFAULT 0 COMMENT '盲盒库存',
  `blindbox_num` int(11) NOT NULL DEFAULT 0 COMMENT '已拆数量',
  `price` decimal(10,2) NOT NULL DEFAULT 0.00 COMMENT '拆盒价格',
  `new_price` decimal(10,2) NOT NULL DEFAULT 0.00 COMMENT '新人拆盒价',
