  `early_inventory` int(11) NOT NULL DEFAULT 0 COMMENT '预警库存',
  `create_time` int(11) NOT NULL DEFAULT 0 COMMENT '创建时间'
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_general_ci COMMENT='盲盒表';

