CREATE TABLE `ns_export` (
  `export_id` int(11) NOT NULL,
  `from_type` varchar(50) NOT NULL DEFAULT '' COMMENT '来源方式',
  `from_type_name` varchar(50) NOT NULL DEFAULT '' COMMENT '来源方式名称',
  `condition` varchar(2000) NOT NULL DEFAULT '' COMMENT '条件  json',
  `status` int(11) NOT NULL DEFAULT 0 COMMENT '状态  0 导出中 1 导出成功  2 导出失败',
  `fail_log` varchar(2000) DEFAULT '' COMMENT '失败日志',
  `create_time` int(11) NOT NULL DEFAULT 0 COMMENT '导出时间',
  `path` varchar(255) NOT NULL DEFAULT '' COMMENT '导出文件的物理路径',
  `site_id` int(11) NOT NULL DEFAULT 0 COMMENT '站点id',
  `store_id` int(11) NOT NULL DEFAULT 0 COMMENT '门店id',
  `data_num` int(11) NOT NULL DEFAULT 0 COMMENT '导出数据条数'
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_general_ci COMMENT='导出记录表';

--
-- 转存表中的数据 `ns_export`
