--
-- 表的结构 `ns_express_delivery_package`
--

CREATE TABLE `ns_express_delivery_package` (
  `id` int(11) NOT NULL,
  `site_id` int(11) NOT NULL DEFAULT 0 COMMENT '站点id',
  `order_id` int(11) NOT NULL DEFAULT 0 COMMENT '订单id',
  `order_goods_id_array` varchar(1000) NOT NULL DEFAULT '' COMMENT '订单项商品组合列表',
  `goods_id_array` text DEFAULT NULL COMMENT '商品组合列表',
  `package_name` varchar(50) NOT NULL DEFAULT '' COMMENT '包裹名称（包裹- 1 包裹 - 2）',
  `delivery_type` tinyint(4) NOT NULL DEFAULT 0 COMMENT '发货方式1 需要物流 0无需物流',
  `express_company_id` int(11) NOT NULL DEFAULT 0 COMMENT '快递公司id',
  `express_company_name` varchar(255) NOT NULL DEFAULT '' COMMENT '物流公司名称',
  `delivery_no` varchar(50) NOT NULL DEFAULT '' COMMENT '运单编号',
  `delivery_time` int(11) NOT NULL DEFAULT 0 COMMENT '发货时间',
  `member_id` int(11) NOT NULL DEFAULT 0 COMMENT '会员id',
  `member_name` varchar(50) NOT NULL DEFAULT '' COMMENT '会员名称',
  `express_company_image` varchar(255) NOT NULL DEFAULT '' COMMENT '发货公司图片',
  `type` varchar(20) NOT NULL DEFAULT '' COMMENT '发货方式（manual 手动发货  electronicsheet 电子面单发货）',
  `template_id` int(11) NOT NULL DEFAULT 0 COMMENT '电子面单模板id',
  `template_name` varchar(255) NOT NULL DEFAULT '' COMMENT '电子面单模板名称',
  `trace` text DEFAULT NULL COMMENT '物流轨迹',
  `follow_waybill_token` varchar(255) NOT NULL DEFAULT '' COMMENT 'follow_waybill返回的waybill_token',
  `follow_waybill_status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '0未传 1成功 -1失败',
  `follow_waybill_time` int(11) NOT NULL DEFAULT 0 COMMENT '最后一次传运单时间',
  `follow_waybill_err` varchar(500) NOT NULL DEFAULT '' COMMENT '失败原因/errmsg',
  `upload_shipping_status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '0未传 1成功 -1失败',
  `upload_shipping_err` varchar(500) NOT NULL DEFAULT '' COMMENT 'uploadShippingInfo 失败原因',
  `upload_shipping_retry` int(11) NOT NULL DEFAULT 0 COMMENT '补传重试次数',
  `follow_delivery_id` varchar(32) NOT NULL DEFAULT '' COMMENT '传运单时使用的微信delivery_id',
  `trace_plugin_token` varchar(255) NOT NULL DEFAULT '' COMMENT 'trace_waybill返回的waybill_token(查询组件专用)',
  `trace_plugin_status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '0未传 1成功 -1失败',
  `trace_plugin_time` int(11) NOT NULL DEFAULT 0 COMMENT '最后一次trace_waybill时间',
  `trace_plugin_err` varchar(500) NOT NULL DEFAULT '' COMMENT 'trace_waybill失败原因',
  `trace_plugin_delivery_id` varchar(32) NOT NULL DEFAULT '' COMMENT 'trace_waybill使用的delivery_id'
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_general_ci COMMENT='商品订单物流信息表（多次发货）';

--
