-- 表的结构 `ns_giftcard_card_blessing`
--

CREATE TABLE `ns_giftcard_card_blessing` (
  `blessing_id` int(11) NOT NULL,
  `site_id` int(11) NOT NULL DEFAULT 0 COMMENT '站点id',
