-- --------------------------------------------------------

--
-- 表的结构 `ns_goods_attribute`
--

CREATE TABLE `ns_goods_attribute` (
  `attr_id` int(11) NOT NULL,
  `attr_name` varchar(50) NOT NULL DEFAULT '' COMMENT '属性名称',
  `attr_class_id` int(11) NOT NULL DEFAULT 0 COMMENT '商品类型id',
  `attr_class_name` varchar(50) NOT NULL DEFAULT '' COMMENT '商品类型名称',
  `sort` int(11) NOT NULL DEFAULT 0 COMMENT '属性排序号',
  `is_query` int(11) NOT NULL DEFAULT 0 COMMENT '是否参与筛选',
  `is_spec` int(11) NOT NULL DEFAULT 0 COMMENT '是否是规格属性',
  `attr_value_list` varchar(255) NOT NULL DEFAULT '' COMMENT '属性值列表（'',''隔开注意键值对）',
  `attr_value_format` text DEFAULT NULL COMMENT '属性值格式json',
  `attr_type` int(11) NOT NULL DEFAULT 0 COMMENT '属性类型  （1.单选 2.多选3. 输入 注意输入不参与筛选）',
  `site_id` int(11) NOT NULL DEFAULT 0 COMMENT '站点id',
  `site_name` varchar(50) NOT NULL DEFAULT '' COMMENT '店铺名称'
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_general_ci COMMENT='商品属性';

-- --------------------------------------------------------

--
-- 表的结构 `ns_goods_attribute_value`
--

CREATE TABLE `ns_goods_attribute_value` (
  `attr_value_id` int(11) NOT NULL,
  `attr_value_name` varchar(50) NOT NULL DEFAULT '' COMMENT '属性值名称',
  `attr_id` int(11) NOT NULL DEFAULT 0 COMMENT '属性id',
  `attr_class_id` int(11) NOT NULL DEFAULT 0 COMMENT '类型id',
  `sort` int(11) NOT NULL DEFAULT 0 COMMENT '排序'
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_general_ci COMMENT='商品属性值表';

-- --------------------------------------------------------

--
-- 表的结构 `ns_goods_attr_class`
--

CREATE TABLE `ns_goods_attr_class` (
  `class_id` int(11) NOT NULL,
  `class_name` varchar(50) NOT NULL DEFAULT '' COMMENT '类型名称',
  `site_id` int(11) NOT NULL DEFAULT 0 COMMENT '所属店铺id',
  `sort` int(11) NOT NULL DEFAULT 0 COMMENT '排序号'
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_general_ci COMMENT=' 商品类型';

-- --------------------------------------------------------

--
-- 表的结构 `ns_goods_brand`
--

CREATE TABLE `ns_goods_brand` (
  `brand_id` bigint(20) NOT NULL COMMENT '索引ID',
  `brand_name` varchar(100) NOT NULL DEFAULT '' COMMENT '品牌名称',
  `brand_initial` varchar(1) NOT NULL DEFAULT '' COMMENT '品牌首字母',
  `image_url` varchar(255) NOT NULL DEFAULT '' COMMENT '品牌logo',
  `banner` varchar(255) NOT NULL DEFAULT '' COMMENT '品牌广告图',
  `brand_desc` varchar(1000) NOT NULL DEFAULT '' COMMENT '品牌简介',
  `site_id` int(11) NOT NULL DEFAULT 0 COMMENT '所属店铺id',
  `sort` int(11) NOT NULL DEFAULT 0 COMMENT '排序',
  `create_time` int(11) NOT NULL DEFAULT 0 COMMENT '创建时间',
  `is_recommend` tinyint(4) NOT NULL DEFAULT 0 COMMENT '是否推荐'
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_general_ci COMMENT='商品品牌表';

