--
-- 表的结构 `ns_goods_virtual`
--

CREATE TABLE `ns_goods_virtual` (
  `id` int(11) NOT NULL,
  `site_id` int(11) NOT NULL DEFAULT 0 COMMENT '店铺id',
  `order_id` int(11) NOT NULL DEFAULT 0 COMMENT '订单id',
  `order_no` varchar(255) NOT NULL DEFAULT '' COMMENT '订单编号',
  `sku_id` int(11) NOT NULL DEFAULT 0 COMMENT '商品sku_id',
  `sku_name` varchar(255) NOT NULL DEFAULT '' COMMENT '商品名称',
  `code` varchar(255) NOT NULL DEFAULT '' COMMENT '虚拟商品编码',
  `is_veirfy` int(11) NOT NULL DEFAULT 0 COMMENT '是否已经核销',
  `verify_time` int(11) NOT NULL DEFAULT 0 COMMENT '核销时间',
  `member_id` int(11) NOT NULL DEFAULT 0 COMMENT '所属人',
  `sku_image` varchar(255) NOT NULL DEFAULT '' COMMENT '虚拟商品图片',
  `expire_time` int(11) NOT NULL DEFAULT 0 COMMENT '核销有效期 0永久 ',
  `card_info` varchar(2500) NOT NULL DEFAULT '' COMMENT '卡密信息',
  `sold_time` int(11) NOT NULL DEFAULT 0 COMMENT '售出时间',
  `goods_id` int(11) NOT NULL DEFAULT 0 COMMENT '商品id',
  `verify_total_count` int(11) NOT NULL DEFAULT 0 COMMENT '核销次数',
  `verify_use_num` int(11) NOT NULL DEFAULT 0 COMMENT '已核销次数'
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_general_ci COMMENT='用户虚拟商品表';

-- --------------------------------------------------------

--
-- 表的结构 `ns_goods_weapp`
--

CREATE TABLE `ns_goods_weapp` (
  `id` int(11) UNSIGNED NOT NULL COMMENT '主键',
  `goods_id` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '商品ID，对应 ns_goods.goods_id',
  `weapp_id` int(11) NOT NULL DEFAULT 0 COMMENT '小程序ID，对应 ns_weapp.weapp_id',
  `is_show` tinyint(1) NOT NULL DEFAULT 1 COMMENT '是否在该小程序上架展示：1是 0否',
  `sort` int(11) NOT NULL DEFAULT 0 COMMENT '端内排序（可选）',
  `create_time` int(11) NOT NULL DEFAULT 0 COMMENT '创建时间',
  `modify_time` int(11) NOT NULL DEFAULT 0 COMMENT '修改时间'
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_general_ci COMMENT='商品小程序可见性表';

