INSERT INTO `ns_member_level` (`level_id`, `site_id`, `level_name`, `sort`, `growth`, `remark`, `is_default`, `is_free_shipping`, `consume_discount`, `point_feedback`, `send_point`, `send_balance`, `send_coupon`, `level_type`, `charge_rule`, `charge_type`, `card_price`, `valid_days`, `bg_color`, `status`, `is_recommend`, `level_background`, `level_text_color`, `level_picture`) VALUES
(1, 1, '新蕊会员', 1, '1.00', '欢迎加入云栖臻源，探索美的起点。我们为您准备了专属见面礼。', 1, 0, '100.00', '1.00', 100, '5.00', '2', 0, '', 0, '0.00', 0, '#F0F9FF', 1, 0, '', '#5D9CEC', 'upload/1/common/images/20260301/20260301072913177236455323966.png'),
(2, 1, '绽妍会员', 1, '500.00', '感谢每一次关注与选择，您的美丽正悄然绽放，享受更暖心的礼遇。', 0, 0, '95.00', '1.20', 300, '15.00', '1', 0, '', 0, '0.00', 0, '#FFF0F5', 1, 0, '', '#FF6B9D', 'upload/1/common/images/20260301/20260301073519177236491961231.png'),
(3, 1, '焕彩会员', 1, '2000.00', '您是栖月汇珍视的核心会员，我们为您提供专属顾问与优先体验权，让美丽光彩照人。', 0, 1, '90.00', '1.50', 800, '50.00', '4', 0, '', 0, '0.00', 0, '#F3E5F5', 1, 0, '', '#9C27B0', 'upload/1/common/images/20260302/20260302112918177242215805010.png'),
(4, 1, '悦享星卡', 1, '0.00', '星芒银卡,让你拥有比其他会员更优惠的爆品特权价，还能收到领取3张满减优惠券，及新品体验官优先报名权', 0, 0, '100.00', '0.00', 0, '5.00', '1,3,4', 1, '', 0, '99.00', 180, '#0F1A2F', 1, 0, '', '#E8F1FF', 'upload/1/common/images/20260517/20260517122159177894851938791.jpg'),
(5, 1, '创盈尊享卡', 1, '0.00', '流光金卡给尊贵的栖月汇代理，你的特权是代理专享价（低至零售价5-6折），每季度新品培训与选品会席位给你预留，在生日月专享赠品与“进货满赠”券\"\n', 0, 0, '100.00', '0.00', 0, '0.00', '1,3,4', 1, '', 0, '6980.00', 365, ' #F5E6C8', 1, 0, '', '#333333', 'upload/1/common/images/20260517/20260517123244177894916419039.jpeg'),
(6, 1, '汇通臻享黑金卡', 1, '0.00', '深邃黑卡，专门为渠道定制的特权：渠道批发价（低于零售价4折）\n，专属渠道经理1对1服务\"\n1. 45套断黑王正装大套\n2. 100套断黑王品鉴套\n3. 三张满减大额优惠券\n3. 终身的拿货价\n', 0, 0, '100.00', '0.00', 0, '0.00', '4,3,1,5', 1, '', 0, '30000.00', 730, '#1A1A1A', 1, 0, '', '#B8860B', 'upload/1/common/images/20260517/20260517125719177895063905780.jpeg'),
(7, 1, '宸极至臻卡', 1, '0.00', '玄墨至尊卡，象征着创始人股东的至高身份，享有股东内部价，无限次新品“创始内测”资格，享有年度利润分红报告与专属答谢礼遇\"\n', 0, 0, '100.00', '0.00', 0, '0.00', '4,3,1', 1, '', 0, '100000.00', 730, '#0A0A0A', 1, 0, '', '#FFD700', 'upload/1/common/images/20260517/20260517074139177897489994582.jpg'),
(8, 1, '测试会员卡', 1, '0.00', '用于临时测试线上功能（请不要购买，不要删除）', 0, 0, '100.00', '0.00', 0, '0.00', '5,2,3,4,1', 1, '', 0, '1.00', 1024, '#333333', 1, 0, '', '#ffffff', 'upload/1/common/images/20260517/20260517113511177898891139630.jpg'),
(9, 1, '鎏光会员', 1, '2200.00', '时光淬炼 美自成光。\n感谢您一路相伴，解锁更多奢宠礼遇 让每一份偏爱都被温柔回应。', 0, 0, '85.00', '1.00', 1000, '5.00', '8', 0, '', 0, '0.00', 0, '#333333', 1, 0, '', '#ffffff', 'upload/1/common/images/20260521/20260521014930177934257062124.jpg'),
(10, 1, '星曜会员', 1, '2400.00', '您是栖月汇的闪耀星芒 专属奢宠通道已为您开启 定制级服务与限定臻礼 只为不负您的每一份信赖。', 0, 0, '80.00', '1.00', 1200, '8.00', '9', 0, '', 0, '0.00', 0, '#333333', 1, 0, '', '#ffffff', 'upload/1/common/images/20260521/20260521021248177934396875575.jpg'),
(11, 1, '臻颜会员', 1, '2600.00', '以匠心守护您的高光时刻，\n私享一对一专属美学顾问、限量新品优先品鉴权，\n让您的美始终走在前沿。\n', 0, 0, '75.00', '1.00', 1200, '10.00', '10', 0, '', 0, '0.00', 0, '#333333', 1, 0, '', '#ffffff', 'upload/1/common/images/20260521/20260521021545177934414530169.jpg'),
(12, 1, '尊奢会员', 1, '2800.00', '您是栖月汇的尊贵挚友 专享年度定制护肤方案 线下沙龙专属席位 让每一次相遇都充满仪式感。', 0, 0, '70.00', '0.00', 1200, '15.00', '11', 0, '', 0, '0.00', 0, '#333333', 1, 0, '', '#ffffff', 'upload/1/common/images/20260521/20260521044015177935281537068.jpg'),
(13, 1, '御颜会员', 1, '3000.00', '时光为序 美无止境。\n您已成为我们的品牌挚友 享全年奢宠礼遇 新品内测资格与品牌联名专属福利。\n', 0, 0, '65.00', '0.00', 1200, '20.00', '12', 0, '', 0, '0.00', 0, '#333333', 1, 0, '', '#ffffff', 'upload/1/common/images/20260521/20260521044310177935299072870.jpg'),
(14, 1, '凤仪会员', 1, '3200.00', '凤仪天成 风华绝代。\n作为栖月汇的至高会员 您将拥有品牌年度限定权益、专属美学管家 尊享从护肤到生活的全方位奢宠。\n', 0, 0, '60.00', '1.00', 1200, '25.00', '13', 0, '', 0, '0.00', 0, '#333333', 1, 0, '', '#ffffff', 'upload/1/common/images/20260521/20260521044532177935313288385.jpg'),
(15, 1, '宸曜会员', 1, '3400.00', '宸光汇聚 耀启不凡。\n您是栖月汇的核心挚友 享私人定制护肤疗程 品牌发布会专属邀约 每一份礼遇都只为匹配您的不凡品味。\n', 0, 0, '55.00', '0.00', 1200, '30.00', '14', 0, '', 0, '0.00', 0, '#333333', 1, 0, '', '#ffffff', 'upload/1/common/images/20260521/20260521044736177935325668362.jpg'),
(16, 1, '天韵会员', 1, '3600.00', '天韵自成，美不设限。\n感谢您的长久陪伴与信赖，您将拥有品牌创始人级别的专属服务 享全球限量臻品优先认购权 让每一份期待都如约而至。\n', 0, 0, '50.00', '1.00', 1200, '35.00', '15', 0, '', 0, '0.00', 0, '#333333', 1, 0, '', '#ffffff', 'upload/1/common/images/20260521/20260521044959177935339948423.jpg'),
(17, 1, '至尊栖月会员', 1, '4000.00', '以您为中心 定义美的最高礼遇。\n作为栖月汇的至尊会员 您将尊享终身定制美学服务 品牌年度私享会专属席位 以及只为您定制的独家臻礼 让时光永远偏爱您。\n', 0, 0, '45.00', '1.00', 1200, '40.00', '', 0, '', 0, '0.00', 0, '#333333', 1, 0, '', '#ffffff', 'upload/1/common/images/20260521/20260521045223177935354387938.jpg'),
(18, 1, '980断黑王特惠专享卡', 1, '0.00', '1.获赠价值399元断黑王超值套餐包 或 399白钻逆龄双效王炸套装：实际购卡成本仅581元\n2. 购物特权，越用越省：凭此卡，超低价购买正装四件套，一次购买直接省下400\n3.回本速度快：推广购卡有高额佣金。成功推广3人，即可回购卡成本，实现“0元持卡”\n4 .全场其他产品专属钜，长期省钱', 0, 0, '100.00', '1.00', 0, '0.00', '4', 1, '', 0, '980.00', 1825, '#333333', 1, 0, '', '#ffffff', 'upload/1/common/images/20260530/20260530034423178012706312012.jpg');

