--
-- 表的结构 `ns_member_log`
--

CREATE TABLE `ns_member_log` (
  `id` int(11) UNSIGNED NOT NULL,
  `member_id` int(11) NOT NULL DEFAULT 0 COMMENT '会员id',
  `action` varchar(255) NOT NULL DEFAULT '' COMMENT '操作行为插件',
