--
-- 表的结构 `ns_member_notice`
--

CREATE TABLE `ns_member_notice` (
  `id` int(11) UNSIGNED NOT NULL,
  `site_id` int(11) NOT NULL DEFAULT 0,
  `member_id` int(11) NOT NULL DEFAULT 0 COMMENT '接收会员',
  `title` varchar(255) NOT NULL DEFAULT '' COMMENT '标题',
  `content` text DEFAULT NULL COMMENT '正文（可存纯文本或JSON）',
  `biz_type` varchar(64) NOT NULL DEFAULT '' COMMENT 'share_exp_* / broadcast_admin 等，见技术方案§9.4',
  `ref_share_instance_id` int(11) UNSIGNED NOT NULL DEFAULT 0,
  `ref_order_id` int(11) NOT NULL DEFAULT 0,
  `is_read` tinyint(4) NOT NULL DEFAULT 0 COMMENT '0未读 1已读',
  `read_time` int(11) NOT NULL DEFAULT 0,
  `ext_json` text DEFAULT NULL COMMENT '批次号、母单id、运营扩展等',
  `create_time` int(11) NOT NULL DEFAULT 0
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_general_ci COMMENT='会员通知（站内持久化）';

