  `point` int(11) NOT NULL DEFAULT 0 COMMENT '积分',
  `growth` int(11) NOT NULL DEFAULT 0 COMMENT '成长值',
  `coupon_id` varchar(255) NOT NULL DEFAULT '0' COMMENT '优惠券ID',
  `price` decimal(10,2) NOT NULL DEFAULT 0.00 COMMENT '实付金额',
  `pay_type` varchar(20) NOT NULL DEFAULT '' COMMENT '支付方式',
  `pay_type_name` varchar(255) NOT NULL DEFAULT '' COMMENT '支付方式名称',
  `status` varchar(255) NOT NULL DEFAULT '1' COMMENT '支付状态（1未支付 2已支付）',
  `create_time` int(11) NOT NULL DEFAULT 0 COMMENT '创建时间',
  `pay_time` int(11) NOT NULL DEFAULT 0 COMMENT '支付时间',
  `member_id` int(11) NOT NULL DEFAULT 0 COMMENT '用户ID',
  `member_img` varchar(255) NOT NULL DEFAULT '' COMMENT '用户头像',
  `nickname` varchar(255) NOT NULL DEFAULT '' COMMENT '用户昵称',
  `order_from` varchar(50) NOT NULL DEFAULT '' COMMENT '订单来源',
  `order_from_name` varchar(255) NOT NULL DEFAULT '' COMMENT '订单来源名称',
  `store_id` int(11) NOT NULL DEFAULT 0 COMMENT '门店id',
  `relate_id` int(11) NOT NULL DEFAULT 0 COMMENT '业务id',
  `relate_type` varchar(255) NOT NULL DEFAULT '' COMMENT '业务类型'
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_general_ci COMMENT='充值卡订单';

-- --------------------------------------------------------

--
-- 表的结构 `ns_member_recommend`
--

CREATE TABLE `ns_member_recommend` (
  `recommend_id` int(11) UNSIGNED NOT NULL,
  `site_id` int(11) NOT NULL DEFAULT 0 COMMENT '站点ID',
  `recommend_name` varchar(255) NOT NULL DEFAULT '' COMMENT '活动名称',
  `start_time` int(11) NOT NULL DEFAULT 0 COMMENT '邀请奖励 开始时间',
  `end_time` int(11) NOT NULL DEFAULT 0 COMMENT '邀请奖励 结束时间',
  `create_time` int(11) NOT NULL DEFAULT 0 COMMENT '创建时间',
  `update_time` int(11) NOT NULL DEFAULT 0 COMMENT '修改时间',
  `status` int(11) NOT NULL DEFAULT 0 COMMENT '状态（0未开始1进行中2已结束-1已关闭）',
  `point` int(11) NOT NULL DEFAULT 0 COMMENT '积分',
  `balance` decimal(10,2) NOT NULL DEFAULT 0.00 COMMENT '余额',
  `coupon` varchar(255) NOT NULL DEFAULT '' COMMENT '优惠券ID  以逗号隔开',
  `max_point` decimal(10,2) NOT NULL DEFAULT 0.00 COMMENT '每月最多积分',
  `max_balance` decimal(10,2) NOT NULL DEFAULT 0.00 COMMENT '每月最多余额',
  `max_coupon` int(11) NOT NULL DEFAULT 0 COMMENT '每月最多优惠券数量',
  `remark` varchar(255) NOT NULL DEFAULT '' COMMENT '备注',
  `type` varchar(255) NOT NULL DEFAULT '' COMMENT '奖励方式',
  `max_fetch` int(11) UNSIGNED DEFAULT 0 COMMENT '每人邀请奖励上限 0为不限制'
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_general_ci;

-- --------------------------------------------------------

--
-- 表的结构 `ns_member_recommend_award`
--

CREATE TABLE `ns_member_recommend_award` (
  `award_id` int(11) UNSIGNED NOT NULL,
  `site_id` int(11) NOT NULL DEFAULT 0 COMMENT '站点ID',
  `recommend_id` int(11) NOT NULL DEFAULT 0 COMMENT '奖励活动ID',
  `recommend_name` varchar(255) NOT NULL DEFAULT '' COMMENT '奖励活动名称',
  `member_id` int(11) NOT NULL DEFAULT 0 COMMENT '奖励人ID',
  `member_nickname` varchar(255) NOT NULL DEFAULT '' COMMENT '奖励人昵称',
  `source_member` int(11) NOT NULL DEFAULT 0 COMMENT '被邀请人ID',
  `source_member_nickname` varchar(255) NOT NULL DEFAULT '' COMMENT '被邀请人昵称',
  `create_time` int(11) NOT NULL DEFAULT 0 COMMENT '创建时间',
  `remark` varchar(255) NOT NULL DEFAULT '' COMMENT '备注',
  `point` decimal(10,2) NOT NULL DEFAULT 0.00 COMMENT '赠送积分',
  `balance` decimal(10,2) NOT NULL DEFAULT 0.00 COMMENT '赠送的余额',
  `coupon` varchar(255) NOT NULL DEFAULT '' COMMENT '优惠券ID',
  `coupon_num` int(11) NOT NULL DEFAULT 0 COMMENT '已发放优惠券数量'
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_general_ci;

-- --------------------------------------------------------

--
-- 表的结构 `ns_member_shop_commission_config`
--

CREATE TABLE `ns_member_shop_commission_config` (
  `id` int(11) UNSIGNED NOT NULL COMMENT '主键',
  `site_id` int(11) NOT NULL DEFAULT 0 COMMENT '站点ID',
  `weapp_id` int(11) NOT NULL DEFAULT 11 COMMENT '小程序端；11=栖月汇',
  `commission_rate` decimal(5,2) NOT NULL DEFAULT 30.00 COMMENT '商品订单分润比例(%)，商城 ns_order 兜底',
  `invest_return_rate` decimal(10,4) NOT NULL DEFAULT 50.0000 COMMENT '目标净利润率F%(投资回报率)',
  `fixed_expense_salary_rate` decimal(10,4) NOT NULL DEFAULT 20.0000 COMMENT '精算固定支出R2:员工工资%',
  `fixed_expense_fund_rate` decimal(10,4) NOT NULL DEFAULT 10.0000 COMMENT '精算固定支出R3:发展基金%',
  `card_commission_rate` decimal(10,4) NOT NULL DEFAULT 0.0000 COMMENT '会员卡购卡推广分润比例(%)，仅 biz_type=super_card_order 使用',
  `share_commission_rate` decimal(10,4) NOT NULL DEFAULT 0.0000 COMMENT '分享成交分润比例(%)，仅 biz_type=share_order',
  `customer_maintenance_rate` decimal(10,4) NOT NULL DEFAULT 0.0000 COMMENT '客户维护分润比例(%)：会员复购实付×比例给上线会员',
  `no_refund_days` int(11) NOT NULL DEFAULT 7 COMMENT '收货后X天不可退款',
  `status` tinyint(4) NOT NULL DEFAULT 1 COMMENT '是否启用 0否 1是',
  `tech_service_status` tinyint(4) NOT NULL DEFAULT 0 COMMENT '是否启用技术服务费 0否1是',
  `tech_service_rate` decimal(10,4) NOT NULL DEFAULT 0.0000 COMMENT '技术服务费比例(%)',
  `tech_service_recipient_openid` varchar(64) NOT NULL DEFAULT '' COMMENT '技术服务费收款微信小程序openid',
  `create_time` int(11) NOT NULL DEFAULT 0 COMMENT '创建时间',
  `update_time` int(11) NOT NULL DEFAULT 0 COMMENT '更新时间'
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_general_ci COMMENT='栖月汇-分润配置表';

