--
-- 表的结构 `ns_member_shop_commission_log`
--

CREATE TABLE `ns_member_shop_commission_log` (
  `id` int(11) UNSIGNED NOT NULL COMMENT '主键',
  `site_id` int(11) NOT NULL DEFAULT 0 COMMENT '站点ID',
  `weapp_id` int(11) NOT NULL DEFAULT 0 COMMENT '订单所属小程序快照',
  `biz_type` varchar(32) NOT NULL DEFAULT 'mall_order' COMMENT '业务类型：mall_order=商城订单 super_card_order=会员卡购卡',
  `order_id` int(11) NOT NULL DEFAULT 0 COMMENT '订单ID',
  `order_no` varchar(50) NOT NULL DEFAULT '' COMMENT '订单编号',
  `biz_summary` varchar(500) NOT NULL DEFAULT '' COMMENT '业务摘要：购卡可写 超级会员卡-{level_name}，商品单可空或商品名拼接',
  `buyer_member_id` int(11) NOT NULL DEFAULT 0 COMMENT '下单会员ID',
  `commission_member_id` int(11) NOT NULL DEFAULT 0 COMMENT '获得分润的会员ID(推广人)',
  `order_money` decimal(10,2) NOT NULL DEFAULT 0.00 COMMENT '订单金额(分润基数)',
  `commission_rate` decimal(10,4) NOT NULL DEFAULT 0.0000 COMMENT '分润等效比例(%)',
  `commission_money` decimal(10,2) NOT NULL DEFAULT 0.00 COMMENT '分润金额',
  `status` tinyint(4) NOT NULL DEFAULT 0 COMMENT '0待打款 1已打款 -1已冲销',
  `pay_time` int(11) NOT NULL DEFAULT 0 COMMENT '打款时间',
  `create_time` int(11) NOT NULL DEFAULT 0 COMMENT '创建时间'
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_general_ci COMMENT='栖月汇-分润明细表';

