--
-- 表的结构 `ns_member_shop_commission_log_line`
--

CREATE TABLE `ns_member_shop_commission_log_line` (
  `id` int(11) UNSIGNED NOT NULL,
  `site_id` int(11) NOT NULL DEFAULT 0,
  `commission_log_id` int(11) NOT NULL DEFAULT 0 COMMENT 'member_shop_commission_log.id',
  `order_id` int(11) NOT NULL DEFAULT 0,
  `order_goods_id` int(11) NOT NULL DEFAULT 0,
  `goods_id` int(11) NOT NULL DEFAULT 0,
  `biz_type` varchar(32) NOT NULL DEFAULT '' COMMENT 'mall_order|share_order',
  `line_base` decimal(10,2) NOT NULL DEFAULT 0.00 COMMENT '行实付y',
  `cost_money` decimal(10,2) NOT NULL DEFAULT 0.00 COMMENT '行成本x',
  `rate_max` decimal(10,4) NOT NULL DEFAULT 0.0000 COMMENT 'a_max或s_max快照%',
  `invest_return_rate` decimal(10,4) NOT NULL DEFAULT 0.0000 COMMENT 'F%快照',
  `fixed_expense_rate` decimal(10,4) NOT NULL DEFAULT 0.0000 COMMENT 'R合计=tech_service_rate+R2+R3快照',
  `cap_rate` decimal(10,4) NOT NULL DEFAULT 0.0000 COMMENT '精算封顶cap%',
  `eff_rate` decimal(10,4) NOT NULL DEFAULT 0.0000 COMMENT '实发eff%',
  `line_commission_money` decimal(10,2) NOT NULL DEFAULT 0.00,
  `is_risk_line` tinyint(1) NOT NULL DEFAULT 0 COMMENT 'cap<0',
  `formula_json` text DEFAULT NULL COMMENT '含tech_service_rate,R2,R3,F,R,cap,eff等',
  `create_time` int(11) NOT NULL DEFAULT 0
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='栖月汇分润计算明细行';

