--
-- 表的结构 `ns_member_shop_share_experience`
--

CREATE TABLE `ns_member_shop_share_experience` (
  `id` int(11) UNSIGNED NOT NULL,
  `site_id` int(11) NOT NULL DEFAULT 0 COMMENT '站点',
  `weapp_id` int(11) NOT NULL DEFAULT 11,
  `owner_member_id` int(11) NOT NULL DEFAULT 0 COMMENT '店主A member_id',
  `source_order_id` int(11) NOT NULL DEFAULT 0 COMMENT '母单 order_id',
  `source_goods_id` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '含N次配置的主商品 goods_id',
  `lead_goods_id` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '引流单品 goods_id',
  `slot_index` smallint(5) UNSIGNED NOT NULL DEFAULT 1 COMMENT '槽位序号 1..N',
  `share_token` varchar(64) NOT NULL DEFAULT '' COMMENT '扫码token，全局唯一',
  `status` tinyint(4) NOT NULL DEFAULT 0 COMMENT '0=有效 1=已关联体验订单 2=已作废',
  `order_id` int(11) NOT NULL DEFAULT 0 COMMENT '体验子单 order_id',
  `shipped_consumed` tinyint(4) NOT NULL DEFAULT 0 COMMENT '0/1 是否已用发货扣减母单剩余次数',
  `qrcode_url` varchar(500) NOT NULL DEFAULT '' COMMENT '小程序码图URL（按需生成缓存）',
  `qrcode_update_time` int(11) NOT NULL DEFAULT 0 COMMENT '码图生成/更新时间戳',
  `create_time` int(11) NOT NULL DEFAULT 0,
  `update_time` int(11) NOT NULL DEFAULT 0
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_general_ci COMMENT='分享体验实例（槽位）';

