CREATE TABLE `ns_member_shop_super_card_commission` (
  `id` int(11) UNSIGNED NOT NULL COMMENT '主键',
  `site_id` int(11) NOT NULL DEFAULT 0 COMMENT '站点ID',
  `weapp_id` int(11) NOT NULL DEFAULT 11 COMMENT '小程序端；11=栖月汇 10=源仓集 9=聚味台',
  `level_id` int(11) NOT NULL DEFAULT 0 COMMENT '超级会员卡 level_id（ns_member_level.level_id，level_type=1）',
  `card_commission_rate` decimal(10,4) DEFAULT NULL COMMENT '购卡推广分润(%)；NULL=未配置，走站点 card_commission_rate 兜底',
  `update_time` int(11) NOT NULL DEFAULT 0 COMMENT '更新时间'
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_general_ci COMMENT='栖月汇-超级会员卡按卡购卡推广分润比例';

