--
-- 表的结构 `ns_member_super_card_evaluate`
--

CREATE TABLE `ns_member_super_card_evaluate` (
  `evaluate_id` int(11) UNSIGNED NOT NULL COMMENT '评价ID',
  `site_id` int(11) NOT NULL DEFAULT 0 COMMENT '站点ID',
  `level_id` int(11) NOT NULL DEFAULT 0 COMMENT '超级会员卡 level_id',
  `level_name` varchar(255) NOT NULL DEFAULT '' COMMENT '卡名称冗余',
  `order_id` int(11) NOT NULL DEFAULT 0 COMMENT 'ns_member_level_order.order_id',
  `order_no` varchar(50) NOT NULL DEFAULT '' COMMENT '购卡订单号',
  `holding_id` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '持仓ID(可选)',
  `member_id` int(11) NOT NULL DEFAULT 0 COMMENT '评价会员',
  `member_name` varchar(255) NOT NULL DEFAULT '' COMMENT '昵称',
  `member_headimg` varchar(500) NOT NULL DEFAULT '' COMMENT '头像',
  `content` text DEFAULT NULL COMMENT '评价内容',
  `images` varchar(3000) NOT NULL DEFAULT '' COMMENT '图片,逗号分隔',
  `videos` varchar(2000) NOT NULL DEFAULT '' COMMENT '视频,逗号分隔',
  `scores` decimal(3,1) NOT NULL DEFAULT 5.0 COMMENT '评分1-5',
  `explain_type` tinyint(1) NOT NULL DEFAULT 1 COMMENT '1好评2中评3差评',
  `is_anonymous` tinyint(1) NOT NULL DEFAULT 0 COMMENT '0公开1匿名',
  `is_show` tinyint(1) NOT NULL DEFAULT 1 COMMENT '是否展示',
  `is_audit` tinyint(1) NOT NULL DEFAULT 1 COMMENT '0待审1通过2拒绝',
  `explain_first` varchar(2000) NOT NULL DEFAULT '' COMMENT '商家回复',
  `create_time` int(11) NOT NULL DEFAULT 0 COMMENT '创建时间'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='超级会员卡购卡评价';

--
-- 转存表中的数据 `ns_member_super_card_evaluate`
--

INSERT INTO `ns_member_super_card_evaluate` (`evaluate_id`, `site_id`, `level_id`, `level_name`, `order_id`, `order_no`, `holding_id`, `member_id`, `member_name`, `member_headimg`, `content`, `images`, `videos`, `scores`, `explain_type`, `is_anonymous`, `is_show`, `is_audit`, `explain_first`, `create_time`) VALUES
