--
-- 表的结构 `ns_member_super_card_holding`
--

CREATE TABLE `ns_member_super_card_holding` (
  `holding_id` int(11) UNSIGNED NOT NULL COMMENT '持仓主键',
  `site_id` int(11) NOT NULL DEFAULT 0 COMMENT '站点ID',
  `member_id` int(11) NOT NULL DEFAULT 0 COMMENT '会员ID',
  `level_id` int(11) NOT NULL DEFAULT 0 COMMENT '付费档ID，对应 ns_member_level.level_id 且 level_type=1',
  `level_name` varchar(255) NOT NULL DEFAULT '' COMMENT '冗余等级名称，便于列表展示',
  `expire_time` int(11) NOT NULL DEFAULT 0 COMMENT '到期时间戳；有效持仓应 >0',
  `status` tinyint(1) NOT NULL DEFAULT 1 COMMENT '1=有效 0=失效(过期/运营作废)',
  `source_type` varchar(32) NOT NULL DEFAULT '' COMMENT '来源：buy=购卡 renew=续费 admin_gift=后台赠卡',
  `source_order_id` int(11) NOT NULL DEFAULT 0 COMMENT '关联 ns_member_level_order.order_id，赠卡可为0',
  `remark` varchar(500) NOT NULL DEFAULT '' COMMENT '备注，如赠卡原因',
  `create_time` int(11) NOT NULL DEFAULT 0 COMMENT '创建时间',
  `update_time` int(11) NOT NULL DEFAULT 0 COMMENT '更新时间'
