--
-- 表的结构 `ns_message`
--

CREATE TABLE `ns_message` (
  `id` int(11) UNSIGNED NOT NULL COMMENT '主键',
  `site_id` int(11) NOT NULL DEFAULT 0 COMMENT '站点id',
  `weapp_id` int(11) NOT NULL DEFAULT 0 COMMENT '模板所属小程序',
  `keywords` varchar(50) NOT NULL DEFAULT '' COMMENT '关键字',
  `sms_is_open` tinyint(4) NOT NULL DEFAULT 0 COMMENT '短信消息是否启动',
  `wechat_is_open` int(11) NOT NULL DEFAULT 0 COMMENT '微信公众号消息',
  `wechat_template_id` varchar(255) NOT NULL DEFAULT '' COMMENT '微信公众号ID',
  `weapp_is_open` int(11) NOT NULL DEFAULT 0 COMMENT '微信小程序是否启动',
  `weapp_template_id` varchar(1000) NOT NULL DEFAULT '' COMMENT '微信小程序配置参数',
  `aliapp_is_open` int(11) NOT NULL DEFAULT 0 COMMENT '支付宝小程序是否启动',
  `aliapp_template_id` varchar(1000) NOT NULL DEFAULT '' COMMENT '支付宝小程序配置参数'
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_general_ci COMMENT='消息管理';

