--
-- 表的结构 `ns_order_import_file`
--

CREATE TABLE `ns_order_import_file` (
  `id` int(11) NOT NULL,
  `site_id` int(11) NOT NULL DEFAULT 0,
  `filename` varchar(255) NOT NULL DEFAULT '' COMMENT '文件名称',
  `path` varchar(255) NOT NULL DEFAULT '' COMMENT '地址',
  `order_num` int(11) NOT NULL DEFAULT 0 COMMENT '导入的订单数',
  `success_num` int(11) NOT NULL DEFAULT 0 COMMENT '成功数',
  `error_num` int(11) NOT NULL DEFAULT 0 COMMENT '失败数',
  `create_time` int(11) NOT NULL DEFAULT 0,
  `delivery_time` int(11) NOT NULL DEFAULT 0 COMMENT '发货时间',
  `uid` int(11) NOT NULL,
  `username` varchar(255) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_general_ci COMMENT='订单批量导入发货';

-- --------------------------------------------------------

--
-- 表的结构 `ns_order_import_file_log`
--

CREATE TABLE `ns_order_import_file_log` (
  `id` int(11) NOT NULL,
  `site_id` int(11) NOT NULL DEFAULT 0,
  `file_id` int(11) NOT NULL DEFAULT 0 COMMENT '上传文件id',
  `order_no` varchar(255) NOT NULL DEFAULT '' COMMENT '订单编号',
  `order_name` varchar(255) NOT NULL DEFAULT '' COMMENT '订单内容',
  `status` tinyint(4) NOT NULL DEFAULT 0 COMMENT '状态',
  `reason` varchar(255) NOT NULL DEFAULT '' COMMENT '原因'
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_general_ci COMMENT='订单导入明细';

-- --------------------------------------------------------

--
-- 表的结构 `ns_order_log`
--

CREATE TABLE `ns_order_log` (
  `id` int(11) NOT NULL,
  `order_id` int(11) NOT NULL DEFAULT 0 COMMENT '订单id',
  `action` varchar(255) NOT NULL DEFAULT '' COMMENT '操作内容',
  `uid` int(11) NOT NULL DEFAULT 0 COMMENT '操作人id',
  `nick_name` varchar(50) NOT NULL DEFAULT '' COMMENT '操作人名称',
  `order_status` int(11) NOT NULL DEFAULT 0 COMMENT '订单状态，操作后',
  `action_way` bigint(20) NOT NULL DEFAULT 2 COMMENT '操作类型1买家2卖家 3 系统任务',
  `order_status_name` varchar(255) NOT NULL DEFAULT '' COMMENT '订单状态名称，操作后',
  `action_time` int(11) NOT NULL DEFAULT 0 COMMENT '操作时间'
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_general_ci COMMENT='订单操作表(传统表，不用设计)';

