--
-- 表的结构 `ns_pay`
--

CREATE TABLE `ns_pay` (
  `id` int(11) UNSIGNED NOT NULL COMMENT '主键',
  `site_id` int(11) NOT NULL DEFAULT 0 COMMENT '站点id',
  `weapp_id` int(11) NOT NULL DEFAULT 0 COMMENT 'pay weapp_id snapshot',
  `mch_id` varchar(32) NOT NULL DEFAULT '' COMMENT 'wechat mch_id snapshot',
  `pay_appid` varchar(32) NOT NULL DEFAULT '' COMMENT 'pay appid snapshot',
  `out_trade_no` varchar(255) NOT NULL DEFAULT '' COMMENT '支付流水号',
  `pay_type` varchar(255) NOT NULL DEFAULT '' COMMENT '支付方式',
  `trade_no` varchar(255) NOT NULL DEFAULT '' COMMENT '交易单号',
  `pay_no` varchar(255) NOT NULL DEFAULT '' COMMENT '支付账号',
  `pay_body` varchar(1000) NOT NULL DEFAULT '' COMMENT '支付主体',
  `pay_detail` varchar(1000) NOT NULL DEFAULT '' COMMENT '支付详情',
  `pay_money` decimal(10,2) NOT NULL DEFAULT 0.00 COMMENT '支付金额',
  `pay_addon` varchar(255) NOT NULL DEFAULT '' COMMENT '支付插件',
  `pay_voucher` varchar(255) NOT NULL DEFAULT '' COMMENT '支付票据',
  `pay_status` int(11) NOT NULL DEFAULT 0 COMMENT '支付状态（0.待支付 1. 支付中 2. 已支付 -1已取消 -2已关闭）',
  `return_url` varchar(255) NOT NULL DEFAULT '' COMMENT '同步回调网址',
  `event` varchar(255) NOT NULL DEFAULT '' COMMENT '支付成功后事件(事件，网址)',
  `mch_info` varchar(1000) NOT NULL DEFAULT '' COMMENT '商户信息',
  `create_time` int(11) NOT NULL DEFAULT 0 COMMENT '创建时间',
  `pay_time` int(11) NOT NULL DEFAULT 0 COMMENT '支付时间',
  `balance` decimal(10,2) NOT NULL DEFAULT 0.00 COMMENT '不可提现余额',
  `balance_money` decimal(10,2) NOT NULL DEFAULT 0.00 COMMENT '可提现余额',
  `member_id` int(11) NOT NULL DEFAULT 0 COMMENT '支付会员id',
  `pay_json` varchar(255) NOT NULL DEFAULT '' COMMENT '支付扩展用支付信息',
  `is_delete` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否删除 1是 0否',
  `relate_id` varchar(255) NOT NULL DEFAULT '' COMMENT '关联id'
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_general_ci COMMENT='支付记录';

