--
-- 表的结构 `ns_pay_offline`
--

CREATE TABLE `ns_pay_offline` (
  `id` int(11) NOT NULL,
  `member_id` int(11) NOT NULL DEFAULT 0 COMMENT '会员id',
  `out_trade_no` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '外部交易号',
  `desc` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '支付说明',
  `imgs` varchar(3000) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '支付图片，多张用逗号分割',
  `status` tinyint(4) NOT NULL COMMENT '状态 0待审核 1审核通过 2审核拒绝 3已取消',
  `audit_remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '审核备注',
