--
-- 表的结构 `ns_pay_refund`
--

CREATE TABLE `ns_pay_refund` (
  `id` int(11) UNSIGNED NOT NULL COMMENT '主键',
  `site_id` int(11) NOT NULL DEFAULT 0 COMMENT '站点id',
  `order_goods_id` int(11) NOT NULL DEFAULT 0 COMMENT '关联订单项 order_goods_id',
  `refund_no` varchar(255) NOT NULL DEFAULT '' COMMENT '退款编号',
  `wx_refund_id` varchar(64) NOT NULL DEFAULT '' COMMENT '微信退款单号 refund_id',
  `wx_status` varchar(32) NOT NULL DEFAULT '' COMMENT '微信退款状态 SUCCESS/PROCESSING/CLOSED/ABNORMAL',
  `channel_status` tinyint(4) NOT NULL DEFAULT 0 COMMENT '渠道状态 0待确认 1成功 2处理中 3关闭 4异常',
  `wx_success_time` int(11) NOT NULL DEFAULT 0 COMMENT '微信退款成功时间戳',
  `last_notify_at` int(11) NOT NULL DEFAULT 0 COMMENT '最近一次回调/查单更新时间',
  `wx_apply_response` text DEFAULT NULL COMMENT '申请退款接口响应 JSON',
  `wx_last_query_response` text DEFAULT NULL COMMENT '最近一次查单响应 JSON',
  `out_trade_no` varchar(255) NOT NULL DEFAULT '' COMMENT '对应支付流水号',
  `refund_detail` varchar(255) NOT NULL DEFAULT '' COMMENT '退款详情',
  `refund_type` varchar(255) NOT NULL DEFAULT '' COMMENT '退款类型',
  `refund_fee` decimal(10,2) NOT NULL DEFAULT 0.00 COMMENT '退款金额',
  `total_money` decimal(10,2) NOT NULL DEFAULT 0.00 COMMENT '实际支付金额',
  `create_time` int(11) NOT NULL DEFAULT 0 COMMENT '创建时间'
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_general_ci COMMENT='退款记录';

