--
-- 表的结构 `ns_pay_refund_notify_log`
--

CREATE TABLE `ns_pay_refund_notify_log` (
  `id` int(11) UNSIGNED NOT NULL COMMENT '主键',
  `site_id` int(11) NOT NULL DEFAULT 0 COMMENT '站点 id',
  `notify_id` varchar(64) NOT NULL DEFAULT '' COMMENT '微信通知 id，幂等键',
  `event_type` varchar(64) NOT NULL DEFAULT '' COMMENT 'REFUND.SUCCESS / REFUND.CLOSED / REFUND.ABNORMAL',
  `refund_no` varchar(64) NOT NULL DEFAULT '' COMMENT '商户退款单号 out_refund_no',
  `wx_refund_id` varchar(64) NOT NULL DEFAULT '' COMMENT '微信 refund_id',
  `wx_status` varchar(32) NOT NULL DEFAULT '' COMMENT '解密后 status',
  `raw_body` mediumtext DEFAULT NULL COMMENT '原始通知 JSON（脱敏后存储）',
  `create_time` int(11) NOT NULL DEFAULT 0 COMMENT '创建时间'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='微信退款回调幂等日志';

