--
-- 表的结构 `ns_pay_transfer`
--

CREATE TABLE `ns_pay_transfer` (
  `id` int(11) NOT NULL,
  `site_id` int(11) NOT NULL DEFAULT 0 COMMENT '站点id',
  `out_trade_no` varchar(50) NOT NULL DEFAULT '' COMMENT '外部账号单',
  `real_name` varchar(50) NOT NULL DEFAULT '' COMMENT '收款人姓名',
  `amount` decimal(10,2) NOT NULL DEFAULT 0.00 COMMENT '转账金额',
  `desc` varchar(255) NOT NULL DEFAULT '' COMMENT '转账说明',
  `transfer_type` varchar(50) NOT NULL DEFAULT '' COMMENT '收款账户类型 微信wechatpay 支付宝alipay 银行卡bank',
  `account_number` varchar(50) NOT NULL DEFAULT '' COMMENT '收款账户号',
  `is_weapp` int(11) NOT NULL DEFAULT 0 COMMENT '是否小程序',
  `member_id` int(11) NOT NULL DEFAULT 0 COMMENT '会员id',
  `from_type` varchar(50) NOT NULL DEFAULT '' COMMENT '来源类型',
  `status` int(11) NOT NULL DEFAULT 0 COMMENT '转账状态 0：待转账 1：转账中 2：转账成功 3：转账失败 -1：已取消',
  `relate_tag` varchar(50) NOT NULL DEFAULT '' COMMENT '关联关键字',
  `resp_data` text DEFAULT NULL COMMENT '返回数据',
  `create_time` int(11) NOT NULL DEFAULT 0 COMMENT '创建时间',
  `update_time` int(11) NOT NULL DEFAULT 0 COMMENT '更新时间'
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_general_ci COMMENT='系统转账表';

