--
-- 表的结构 `ns_pc_floor`
--

CREATE TABLE `ns_pc_floor` (
  `id` int(11) NOT NULL COMMENT '数据ID',
  `site_id` int(11) NOT NULL DEFAULT 0 COMMENT '所属店铺id',
  `block_id` int(11) NOT NULL DEFAULT 0 COMMENT '模板ID',
  `title` varchar(100) NOT NULL DEFAULT '' COMMENT '楼层标题',
  `value` text DEFAULT NULL COMMENT '配置',
  `state` tinyint(4) NOT NULL DEFAULT 1 COMMENT '状态（0：禁用，1：启用）',
  `create_time` int(11) NOT NULL DEFAULT 0 COMMENT '创建时间',
  `sort` int(11) NOT NULL DEFAULT 0 COMMENT '排序号'
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_general_ci COMMENT='PC端首页楼层';

