CREATE TABLE `ns_pc_friendly_link` (
  `id` int(11) UNSIGNED NOT NULL COMMENT '索引id',
  `site_id` int(11) NOT NULL DEFAULT 0 COMMENT '所属店铺id',
  `link_title` varchar(100) NOT NULL DEFAULT '' COMMENT '标题',
  `link_url` varchar(100) NOT NULL DEFAULT '' COMMENT '链接',
  `link_pic` varchar(100) NOT NULL DEFAULT '' COMMENT '图片',
  `link_sort` int(11) DEFAULT NULL,
  `is_blank` int(11) NOT NULL DEFAULT 1 COMMENT '是否新窗口打开 1.是 2.否',
  `is_show` int(11) NOT NULL DEFAULT 1 COMMENT '是否显示 1.是 2.否'
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_general_ci COMMENT='PC友情链接表';

