--
-- 表的结构 `ns_promotion_coupon_gift_log`
--

CREATE TABLE `ns_promotion_coupon_gift_log` (
  `gift_id` int(11) UNSIGNED NOT NULL COMMENT '赠送流水ID',
  `site_id` int(11) NOT NULL DEFAULT 0 COMMENT '站点ID',
  `gift_mode` tinyint(4) NOT NULL DEFAULT 1 COMMENT '1分享抢券 2指定好友',
  `coupon_id` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '券实例 promotion_coupon.coupon_id',
  `coupon_type_id` int(11) NOT NULL DEFAULT 0 COMMENT '券类型ID（冗余，列表展示）',
  `from_member_id` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '赠送人 A',
  `to_member_id` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '领取人 B；0=尚未绑定',
  `gift_token` varchar(64) NOT NULL DEFAULT '' COMMENT '领取令牌（分享链接参数）',
  `status` tinyint(4) NOT NULL DEFAULT 0 COMMENT '0待领取 1已领取 2已过期 3已撤回',
  `expire_time` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '领取截止时间戳',
  `claim_time` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '领取时间戳',
  `create_time` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '创建时间',
  `update_time` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '更新时间'
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_general_ci COMMENT='优惠券赠送流水';

