--
-- 表的结构 `ns_promotion_discount`
--

CREATE TABLE `ns_promotion_discount` (
  `discount_id` int(11) UNSIGNED NOT NULL COMMENT '主键',
  `site_id` int(11) NOT NULL DEFAULT 1 COMMENT '站点id',
  `site_name` varchar(255) NOT NULL DEFAULT '' COMMENT '站点名称',
  `discount_name` varchar(255) NOT NULL DEFAULT '' COMMENT '活动名称',
  `status` tinyint(4) NOT NULL DEFAULT 0 COMMENT '活动状态 0未开始 1进行中 2已结束 -1已关闭（手动）',
  `remark` varchar(1000) NOT NULL DEFAULT '' COMMENT '备注',
  `start_time` int(11) NOT NULL DEFAULT 0 COMMENT '活动开始时间',
  `end_time` int(11) NOT NULL DEFAULT 0 COMMENT '活动结束时间',
  `create_time` int(11) NOT NULL DEFAULT 0 COMMENT '创建时间',
  `modify_time` int(11) NOT NULL DEFAULT 0 COMMENT '修改时间',
  `goods_id` int(11) NOT NULL DEFAULT 0 COMMENT '商品id',
  `discount_price` decimal(10,2) NOT NULL DEFAULT 0.00 COMMENT '折扣金额，只做展示'
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_general_ci COMMENT='限时折扣';

-- --------------------------------------------------------

--
-- 表的结构 `ns_promotion_discount_goods`
--

CREATE TABLE `ns_promotion_discount_goods` (
  `id` int(11) UNSIGNED NOT NULL COMMENT '主键',
  `discount_id` int(11) NOT NULL DEFAULT 0 COMMENT '对应活动Id',
  `start_time` int(11) NOT NULL DEFAULT 0 COMMENT '活动开始时间',
  `end_time` int(11) NOT NULL DEFAULT 0 COMMENT '活动结束时间',
  `goods_id` int(11) NOT NULL DEFAULT 0 COMMENT '商品id',
  `sku_id` int(11) NOT NULL DEFAULT 0 COMMENT 'skuId',
  `price` decimal(10,2) NOT NULL DEFAULT 0.00 COMMENT '商品价格',
  `discount_price` decimal(10,2) NOT NULL DEFAULT 0.00 COMMENT '折扣价',
  `sku_name` varchar(255) NOT NULL DEFAULT '' COMMENT '商品名称',
  `sku_image` varchar(1000) NOT NULL DEFAULT '' COMMENT '商品图片'
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_general_ci COMMENT='限时折扣商品列表';

-- --------------------------------------------------------

--
-- 表的结构 `ns_promotion_exchange`
--

CREATE TABLE `ns_promotion_exchange` (
  `id` int(11) UNSIGNED NOT NULL COMMENT '主键',
  `site_id` int(11) NOT NULL DEFAULT 0 COMMENT ' 站点id',
  `type` int(11) NOT NULL DEFAULT 1 COMMENT '兑换形式',
  `type_name` varchar(255) NOT NULL DEFAULT '' COMMENT '兑换类型名称',
  `type_id` int(11) NOT NULL DEFAULT 0 COMMENT '关联id',
  `name` varchar(255) NOT NULL DEFAULT '' COMMENT '兑换名称',
  `image` varchar(255) NOT NULL DEFAULT '' COMMENT '图片',
  `stock` int(11) NOT NULL DEFAULT 0 COMMENT '当前库存',
  `pay_type` tinyint(4) NOT NULL DEFAULT 0 COMMENT '支付类型（0积分  1积分加钱）',
  `point` int(11) NOT NULL DEFAULT 0 COMMENT '积分数',
  `market_price` decimal(10,2) NOT NULL DEFAULT 0.00 COMMENT '市场价',
  `price` decimal(10,2) NOT NULL DEFAULT 0.00 COMMENT '兑换价',
  `limit_num` int(11) NOT NULL DEFAULT 0 COMMENT '限制兑换数量',
  `balance` decimal(10,2) NOT NULL DEFAULT 0.00 COMMENT '余额红包（余额有效）',
  `state` int(11) NOT NULL DEFAULT 1 COMMENT '状态（上下架）',
  `content` text DEFAULT NULL COMMENT '兑换说明',
  `create_time` int(11) NOT NULL DEFAULT 0 COMMENT '创建时间',
  `modify_time` int(11) NOT NULL DEFAULT 0 COMMENT '修改时间',
  `sort` int(11) NOT NULL DEFAULT 0 COMMENT '排序',
  `exchange_goods_id` int(11) NOT NULL DEFAULT 0,
  `delivery_price` decimal(10,2) NOT NULL DEFAULT 0.00 COMMENT '物流费用（礼品有效）',
  `delivery_type` tinyint(4) NOT NULL DEFAULT 1 COMMENT '运费类型（ 0 固定运费  1运费模板  2按照商品）',
  `shipping_template` int(11) NOT NULL DEFAULT 0 COMMENT '运费模板',
  `is_free_shipping` tinyint(4) NOT NULL DEFAULT 1 COMMENT '是否免邮（0不免邮  1免邮）',
  `rule` text DEFAULT NULL COMMENT '商品兑换规则'
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_general_ci COMMENT='积分兑换';

-- --------------------------------------------------------

--
-- 表的结构 `ns_promotion_exchange_goods`
--

CREATE TABLE `ns_promotion_exchange_goods` (
  `id` int(11) UNSIGNED NOT NULL COMMENT '主键',
  `site_id` int(11) NOT NULL DEFAULT 0 COMMENT ' 站点id',
  `type` int(11) NOT NULL DEFAULT 1 COMMENT '兑换形式',
  `type_name` varchar(255) NOT NULL DEFAULT '' COMMENT '兑换类型名称',
  `type_id` int(11) NOT NULL DEFAULT 0 COMMENT '关联id',
  `name` varchar(255) NOT NULL DEFAULT '' COMMENT '兑换名称',
  `image` varchar(255) NOT NULL DEFAULT '' COMMENT '图片',
  `point` int(11) NOT NULL DEFAULT 0 COMMENT '积分数',
  `price` decimal(10,2) NOT NULL DEFAULT 0.00 COMMENT '兑换价',
  `balance` decimal(10,2) NOT NULL DEFAULT 0.00 COMMENT '余额红包（余额有效）',
  `state` int(11) NOT NULL DEFAULT 1 COMMENT '状态（上下架）',
  `content` text DEFAULT NULL COMMENT '兑换说明',
  `create_time` int(11) NOT NULL DEFAULT 0 COMMENT '创建时间',
  `modify_time` int(11) NOT NULL DEFAULT 0 COMMENT '修改时间',
  `sort` int(11) NOT NULL DEFAULT 0 COMMENT '排序',
  `pay_type` int(11) NOT NULL DEFAULT 0 COMMENT '兑换类型 0-积分 1-积分+余额',
  `delivery_price` decimal(10,2) NOT NULL DEFAULT 0.00 COMMENT '物流费用（礼品有效）',
  `rule` text DEFAULT NULL COMMENT '兑换规则'
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_general_ci COMMENT='积分兑换(主表)';

-- --------------------------------------------------------

--
-- 表的结构 `ns_promotion_exchange_order`
--

CREATE TABLE `ns_promotion_exchange_order` (
  `order_id` int(11) UNSIGNED NOT NULL,
  `order_no` varchar(255) NOT NULL DEFAULT '' COMMENT '订单编号',
  `member_id` int(11) NOT NULL DEFAULT 0 COMMENT '对应会员',
  `out_trade_no` varchar(255) NOT NULL DEFAULT '' COMMENT '支付流水号（线上支付有效）',
  `point` int(11) NOT NULL DEFAULT 0 COMMENT '兑换积分数',
  `exchange_price` decimal(10,2) NOT NULL DEFAULT 0.00 COMMENT '兑换价格',
  `delivery_price` decimal(10,2) NOT NULL DEFAULT 0.00 COMMENT '邮费',
  `price` decimal(10,2) NOT NULL DEFAULT 0.00 COMMENT '实际应付金额',
  `express_no` varchar(255) NOT NULL DEFAULT '' COMMENT '物流单号（礼品发货）',
  `create_time` int(11) NOT NULL DEFAULT 0 COMMENT '创建时间',
  `pay_time` int(11) NOT NULL DEFAULT 0 COMMENT '兑换成功时间',
  `exchange_id` int(11) NOT NULL DEFAULT 0 COMMENT '兑换商品id',
  `exchange_name` varchar(255) NOT NULL DEFAULT '' COMMENT '兑换商品名称',
  `exchange_image` varchar(255) NOT NULL DEFAULT '' COMMENT '兑换商品图片',
  `num` int(11) NOT NULL DEFAULT 0 COMMENT '兑换数量',
  `order_status` int(11) NOT NULL DEFAULT 0 COMMENT '状态',
  `type` int(11) NOT NULL DEFAULT 0 COMMENT '类型',
  `type_name` varchar(255) NOT NULL DEFAULT '' COMMENT '类型名称',
  `name` varchar(255) NOT NULL DEFAULT '' COMMENT '姓名',
  `mobile` varchar(255) NOT NULL DEFAULT '' COMMENT '手机号',
  `telephone` varchar(255) NOT NULL DEFAULT '' COMMENT '电话',
  `province_id` int(11) NOT NULL DEFAULT 0 COMMENT '省id',
  `city_id` int(11) NOT NULL DEFAULT 0 COMMENT '市id',
  `district_id` int(11) NOT NULL DEFAULT 0 COMMENT '区县id',
  `community_id` int(11) NOT NULL DEFAULT 0 COMMENT '社区id',
  `address` varchar(255) NOT NULL DEFAULT '' COMMENT '地址信息',
  `full_address` varchar(255) NOT NULL DEFAULT '' COMMENT '详细地址信息',
  `longitude` varchar(50) NOT NULL DEFAULT '' COMMENT '经度',
  `latitude` varchar(50) NOT NULL DEFAULT '' COMMENT '纬度',
  `buyer_message` varchar(255) NOT NULL DEFAULT '' COMMENT '买家留言',
  `order_from` varchar(255) NOT NULL DEFAULT '' COMMENT '订单来源',
  `order_from_name` varchar(255) NOT NULL DEFAULT '' COMMENT '订单来源名称',
  `type_id` int(11) NOT NULL DEFAULT 0 COMMENT '关联id',
  `balance` decimal(10,2) NOT NULL DEFAULT 0.00 COMMENT '赠送红包',
  `site_id` int(11) NOT NULL DEFAULT 0,
  `delivery_type` varchar(255) NOT NULL DEFAULT '' COMMENT '物流类型',
  `delivery_type_name` varchar(255) NOT NULL DEFAULT '' COMMENT '配送方式名称',
  `delivery_status` int(11) NOT NULL DEFAULT 0 COMMENT '发货状态',
  `delivery_status_name` varchar(255) NOT NULL DEFAULT '' COMMENT '发货状态名称',
  `delivery_code` varchar(255) NOT NULL DEFAULT '' COMMENT '配送单号',
  `delivery_store_id` int(11) NOT NULL DEFAULT 0 COMMENT '门店id',
  `delivery_store_name` varchar(255) NOT NULL DEFAULT '' COMMENT '门店名称',
  `delivery_store_info` varchar(2000) NOT NULL DEFAULT '' COMMENT '门店信息',
  `buyer_ask_delivery_time` varchar(255) NOT NULL DEFAULT '' COMMENT '到达时间',
  `relate_order_id` int(11) NOT NULL DEFAULT 0 COMMENT '关联订单',
  `exchange_goods_id` int(11) NOT NULL DEFAULT 0 COMMENT '积分兑换主表',
  `order_money` decimal(10,2) NOT NULL DEFAULT 0.00 COMMENT '订单金额',
  `delivery_start_time` int(11) NOT NULL COMMENT '配送开始时间',
  `delivery_end_time` int(11) NOT NULL DEFAULT 0 COMMENT '配送结束时间'
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_general_ci COMMENT='积分兑换订单';

-- --------------------------------------------------------

--
-- 表的结构 `ns_promotion_festival`
--

CREATE TABLE `ns_promotion_festival` (
  `festival_id` int(11) NOT NULL,
  `activity_name` varchar(255) NOT NULL DEFAULT '' COMMENT '活动名',
  `site_id` int(11) NOT NULL DEFAULT 0,
  `festival_name` varchar(255) NOT NULL DEFAULT '' COMMENT '节日名',
  `festival_type` varchar(30) NOT NULL DEFAULT '1' COMMENT '活动类型（插件名称）',
  `festival_type_name` varchar(255) NOT NULL DEFAULT '' COMMENT '活动类型名称',
  `level_id` varchar(255) NOT NULL DEFAULT '' COMMENT '参与的会员等级0表示全部参与',
  `level_name` varchar(255) NOT NULL DEFAULT '' COMMENT '参与活动会员名称',
  `start_time` int(11) NOT NULL DEFAULT 0 COMMENT '活动开始时间',
  `end_time` int(11) NOT NULL DEFAULT 0 COMMENT '结束时间',
  `status` int(11) NOT NULL DEFAULT 0 COMMENT '活动状态 0未开始 1已开始 2已结束 3已关闭',
  `push_time` int(11) NOT NULL DEFAULT 0 COMMENT '活动推送时间',
  `remark` varchar(1000) NOT NULL DEFAULT '' COMMENT '说明',
  `create_time` int(11) NOT NULL DEFAULT 0 COMMENT '创建时间',
  `update_time` int(11) NOT NULL DEFAULT 0 COMMENT '更新时间',
  `join_time` int(11) NOT NULL DEFAULT 0 COMMENT '0自定义节日 1传统节日',
  `join_type` int(11) NOT NULL DEFAULT 0 COMMENT '1活动时间内 0活动开始前',
  `join_frequency` int(11) NOT NULL DEFAULT 0 COMMENT '天数'
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_general_ci;

-- --------------------------------------------------------

--
-- 表的结构 `ns_promotion_festival_award`
--

CREATE TABLE `ns_promotion_festival_award` (
  `award_id` int(11) NOT NULL,
  `site_id` int(11) NOT NULL DEFAULT 0,
  `festival_id` int(11) NOT NULL DEFAULT 0,
  `award_type` varchar(255) NOT NULL DEFAULT '' COMMENT '奖品类型 以逗号分割',
  `coupon` varchar(255) NOT NULL DEFAULT '' COMMENT '关联id（根据奖品类型）',
  `point` int(11) NOT NULL DEFAULT 0 COMMENT '积分数',
  `balance` decimal(10,2) NOT NULL DEFAULT 0.00 COMMENT '余额',
  `award_num` int(11) NOT NULL DEFAULT 0 COMMENT '奖品数量',
  `remaining_num` int(11) NOT NULL DEFAULT 0 COMMENT '剩余数量',
  `receive_num` int(11) NOT NULL DEFAULT 0 COMMENT '已领取数量',
  `balance_type` int(11) NOT NULL DEFAULT 0 COMMENT '0不可提现 1可提现',
  `balance_money` decimal(10,2) NOT NULL DEFAULT 0.00 COMMENT '可提现'
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_general_ci;

-- --------------------------------------------------------

--
-- 表的结构 `ns_promotion_festival_draw_record`
--

CREATE TABLE `ns_promotion_festival_draw_record` (
  `record_id` int(11) NOT NULL,
  `site_id` int(11) NOT NULL DEFAULT 0,
  `festival_id` int(11) NOT NULL DEFAULT 0 COMMENT '活动id',
  `festival_type` varchar(30) NOT NULL DEFAULT '' COMMENT '活动类型（插件名称）',
  `member_id` int(11) NOT NULL DEFAULT 0 COMMENT '会员id',
  `member_nick_name` varchar(255) NOT NULL DEFAULT '' COMMENT '会员昵称',
  `award_id` int(11) NOT NULL DEFAULT 0 COMMENT '奖品id',
  `receive_time` int(11) NOT NULL DEFAULT 0 COMMENT '领取时间'
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_general_ci;

-- --------------------------------------------------------

--
-- 表的结构 `ns_promotion_freeshipping`
--

CREATE TABLE `ns_promotion_freeshipping` (
  `freeshipping_id` int(11) UNSIGNED NOT NULL,
  `site_id` int(11) NOT NULL DEFAULT 0 COMMENT '站点id',
  `price` decimal(10,2) NOT NULL DEFAULT 0.00 COMMENT '金额',
  `area_ids` text DEFAULT NULL COMMENT '地区ids',
  `area_names` text DEFAULT NULL COMMENT '地区名称',
  `surplus_area_ids` text DEFAULT NULL,
  `create_time` int(11) NOT NULL DEFAULT 0,
  `update_time` int(11) NOT NULL DEFAULT 0
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_general_ci COMMENT='满额包邮';

-- --------------------------------------------------------

--
-- 表的结构 `ns_promotion_friends_coupon`
--

CREATE TABLE `ns_promotion_friends_coupon` (
  `coupon_id` int(11) UNSIGNED NOT NULL,
  `site_id` int(11) NOT NULL DEFAULT 0 COMMENT '站点Id',
  `coupon_type_id` int(11) NOT NULL DEFAULT 0 COMMENT '优惠券类型Id',
  `name` varchar(64) NOT NULL DEFAULT '' COMMENT '活动名称',
  `goods_type` int(11) NOT NULL DEFAULT 1 COMMENT '适用商品类型1-全部商品可用；2-指定商品可用；3-指定商品不可用',
  `goods_ids` varchar(2500) NOT NULL DEFAULT '' COMMENT '商品Id',
  `image` varchar(255) NOT NULL DEFAULT '' COMMENT '优惠券图片',
  `start_time` int(11) NOT NULL DEFAULT 0 COMMENT '活动开始时间',
  `end_time` int(11) NOT NULL DEFAULT 0 COMMENT '活动结束时间',
  `status` int(11) NOT NULL DEFAULT 0 COMMENT '状态 0未开始 1进行中 2已结束 -1已关闭',
  `status_name` varchar(64) NOT NULL DEFAULT '' COMMENT '状态名称',
  `count` int(11) NOT NULL DEFAULT 0 COMMENT '发放总量',
  `inventory` int(11) DEFAULT 0 COMMENT '优惠券库存',
  `success_count` int(11) NOT NULL DEFAULT 0 COMMENT '瓜分成功的优惠券数量',
  `money` decimal(10,2) NOT NULL DEFAULT 0.00 COMMENT '优惠券瓜分金额',
  `divide_num` int(11) NOT NULL DEFAULT 0 COMMENT '瓜分人数',
  `validity_type` int(11) NOT NULL DEFAULT 1 COMMENT '过期类型0-固定时间1领取之日起',
  `start_use_time` int(11) NOT NULL DEFAULT 0 COMMENT '使用开始日期 过期类型1时必填',
  `end_use_time` int(11) NOT NULL DEFAULT 0 COMMENT '使用结束日期 过期类型1时必填',
  `fixed_term` int(11) NOT NULL DEFAULT 0 COMMENT '当validity_type为2或者3时需要添加 领取之日起或者次日N天内有效',
  `divide_type` int(11) NOT NULL DEFAULT 0 COMMENT '瓜分方式（0固定金额 1随机金额）',
  `is_simulation` int(11) NOT NULL DEFAULT 0 COMMENT '是否模拟好友 0否 1是',
  `remark` varchar(255) NOT NULL DEFAULT '' COMMENT '活动规则说明',
  `divide_time` int(11) NOT NULL DEFAULT 1 COMMENT '瓜分有效期(小时)',
  `is_limit` int(11) NOT NULL DEFAULT 0 COMMENT '使用门槛 0无门槛 1 有门槛',
  `at_least` decimal(10,2) NOT NULL DEFAULT 0.00 COMMENT '满多少元使用 0代表无限制',
  `is_new` int(11) NOT NULL DEFAULT 0 COMMENT '仅新人参与限制 0否 1是',
  `validity_end_time` int(11) NOT NULL DEFAULT 0 COMMENT '使用券有效期结束时间',
  `create_time` int(11) NOT NULL DEFAULT 0 COMMENT '创建时间'
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_general_ci COMMENT='好友瓜分券活动表';

