--
-- 表的结构 `ns_promotion_friends_coupon_group`
--

CREATE TABLE `ns_promotion_friends_coupon_group` (
  `group_id` int(11) UNSIGNED NOT NULL,
  `promotion_id` int(11) NOT NULL DEFAULT 0 COMMENT '活动Id',
  `coupon_type_id` int(11) NOT NULL DEFAULT 0 COMMENT '优惠券类型Id',
  `start_time` int(11) NOT NULL DEFAULT 0 COMMENT '开始时间',
  `end_time` int(11) NOT NULL DEFAULT 0 COMMENT '结束时间',
  `header_id` int(11) NOT NULL DEFAULT 0 COMMENT '发起人Id',
  `member_ids` varchar(255) NOT NULL DEFAULT '' COMMENT '参与人id',
  `coupon_ids` varchar(255) NOT NULL DEFAULT '' COMMENT '优惠券组Id',
  `group_member_ids` varchar(255) NOT NULL DEFAULT '' COMMENT '组中人id（发放券的人）',
  `num` int(11) NOT NULL DEFAULT 0 COMMENT '参与数量',
  `status` int(11) NOT NULL DEFAULT 0 COMMENT '状态 0进行中 1瓜分成功 2瓜分失败',
  `is_look` int(11) NOT NULL DEFAULT 0 COMMENT '查看区分（瓜分失败后 0是重新组队 1是去查看）',
  `site_id` int(11) NOT NULL DEFAULT 0
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_general_ci COMMENT='好友瓜分券参与活动组';

