--
-- 表的结构 `ns_split_word`
--

CREATE TABLE `ns_split_word` (
  `id` int(11) NOT NULL,
  `keyword` varchar(100) NOT NULL,
  `result` text DEFAULT NULL,
  `add_time` datetime NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='拆词表';

-- --------------------------------------------------------

--
-- 表的结构 `ns_stat_shop`
--

CREATE TABLE `ns_stat_shop` (
  `id` int(11) UNSIGNED NOT NULL,
  `site_id` int(11) NOT NULL DEFAULT 0 COMMENT '站点id',
  `year` int(11) NOT NULL DEFAULT 0 COMMENT '年',
  `month` int(11) NOT NULL DEFAULT 0 COMMENT '月',
  `day` int(11) NOT NULL DEFAULT 0 COMMENT '日',
  `day_time` int(11) NOT NULL DEFAULT 0 COMMENT '当日时间',
  `order_total` decimal(10,2) NOT NULL DEFAULT 0.00 COMMENT '订单金额',
  `shipping_total` decimal(10,2) NOT NULL DEFAULT 0.00 COMMENT '运费金额',
  `refund_total` decimal(10,2) NOT NULL DEFAULT 0.00 COMMENT '退款金额',
  `order_pay_count` int(11) NOT NULL DEFAULT 0 COMMENT '订单总数',
  `goods_pay_count` int(11) NOT NULL DEFAULT 0 COMMENT '订单商品总数',
  `shop_money` decimal(10,2) NOT NULL DEFAULT 0.00 COMMENT '店铺金额',
  `platform_money` decimal(10,2) NOT NULL DEFAULT 0.00 COMMENT '平台金额',
  `create_time` int(11) NOT NULL DEFAULT 0 COMMENT '创建时间',
  `modify_time` int(11) NOT NULL DEFAULT 0 COMMENT '修改时间',
  `collect_shop` int(11) NOT NULL DEFAULT 0 COMMENT '店铺收藏量',
  `collect_goods` int(11) NOT NULL DEFAULT 0 COMMENT '商品收藏量',
  `visit_count` int(11) NOT NULL DEFAULT 0 COMMENT '浏览量',
  `order_count` int(11) NOT NULL DEFAULT 0 COMMENT '订单量（总）',
  `goods_count` int(11) NOT NULL DEFAULT 0 COMMENT '订单商品量（总）',
  `add_goods_count` int(11) NOT NULL DEFAULT 0 COMMENT '添加商品数',
  `member_count` int(11) NOT NULL DEFAULT 0 COMMENT '会员统计',
  `order_member_count` int(11) NOT NULL DEFAULT 0 COMMENT '下单会员数',
  `order_refund_count` int(11) NOT NULL DEFAULT 0 COMMENT '退款订单数',
  `order_refund_grand_count` decimal(10,2) NOT NULL DEFAULT 0.00 COMMENT '退款金额',
  `order_refund_grand_total_money` decimal(10,2) NOT NULL DEFAULT 0.00 COMMENT '累计退款金额',
  `coupon_member_count` int(11) NOT NULL DEFAULT 0 COMMENT '领券会员数量',
  `member_level_count` int(11) NOT NULL DEFAULT 0 COMMENT '超级会员卡销售量',
  `member_level_total_money` decimal(10,2) NOT NULL DEFAULT 0.00 COMMENT '超级会员卡销售额',
  `member_level_grand_count` int(11) NOT NULL DEFAULT 0 COMMENT '累计超级会员卡销售量',
  `member_level_grand_total_money` decimal(10,2) NOT NULL DEFAULT 0.00 COMMENT '累计超级会员卡销售额',
  `member_recharge_count` int(11) NOT NULL DEFAULT 0 COMMENT '会员储值总订单量',
  `member_recharge_grand_count` decimal(10,2) NOT NULL DEFAULT 0.00 COMMENT '累计会员储值总量',
  `member_recharge_total_money` decimal(10,2) NOT NULL DEFAULT 0.00 COMMENT '会员充值总额',
  `member_recharge_grand_total_money` decimal(10,2) NOT NULL DEFAULT 0.00 COMMENT '累计会员充值总额',
  `member_recharge_member_count` int(11) NOT NULL DEFAULT 0 COMMENT '储值会员数',
  `member_giftcard_count` int(11) NOT NULL DEFAULT 0 COMMENT '礼品卡订单总量',
  `member_giftcard_grand_count` int(11) NOT NULL DEFAULT 0 COMMENT '累计礼品卡订单总量',
  `member_giftcard_total_money` decimal(10,2) NOT NULL DEFAULT 0.00 COMMENT '礼品卡订单总额',
  `h5_visit_count` int(11) NOT NULL DEFAULT 0 COMMENT 'h5访问量',
  `wechat_visit_count` int(11) NOT NULL DEFAULT 0 COMMENT 'wechat访问量',
  `weapp_visit_count` int(11) NOT NULL DEFAULT 0 COMMENT 'weapp访问量',
  `pc_visit_count` int(11) NOT NULL DEFAULT 0 COMMENT 'pc访问量',
  `expected_earnings_total_money` decimal(10,2) NOT NULL DEFAULT 0.00 COMMENT '预计收入',
  `expenditure_total_money` decimal(10,2) NOT NULL DEFAULT 0.00 COMMENT '总支出',
  `earnings_total_money` decimal(10,2) NOT NULL DEFAULT 0.00 COMMENT '总收入',
  `member_withdraw_count` int(11) NOT NULL DEFAULT 0 COMMENT '会员提现总量',
  `member_withdraw_total_money` decimal(10,2) NOT NULL DEFAULT 0.00 COMMENT '会员提现总额',
  `coupon_count` int(11) NOT NULL DEFAULT 0 COMMENT '领券数',
  `add_coupon_count` int(11) NOT NULL DEFAULT 0 COMMENT '新增优惠券',
  `order_pay_money` decimal(10,2) NOT NULL DEFAULT 0.00 COMMENT '订单实际支付',
  `add_fenxiao_member_count` int(11) NOT NULL DEFAULT 0 COMMENT '新增分销商',
  `fenxiao_order_total_money` decimal(10,2) NOT NULL DEFAULT 0.00 COMMENT '分销订单总额',
  `fenxiao_order_count` int(11) NOT NULL DEFAULT 0 COMMENT '分销订单总数',
  `goods_on_type_count` int(11) NOT NULL DEFAULT 0 COMMENT '在架商品数',
  `goods_visited_type_count` int(11) NOT NULL DEFAULT 0 COMMENT '被访问商品数(仅详情页浏览数)',
  `goods_order_type_count` int(11) NOT NULL DEFAULT 0 COMMENT '动销商品数',
  `goods_exposure_count` int(11) NOT NULL DEFAULT 0 COMMENT '商品曝光数',
  `goods_visit_count` int(11) NOT NULL DEFAULT 0 COMMENT '商品浏览量',
  `goods_visit_member_count` int(11) NOT NULL DEFAULT 0 COMMENT '商品访客数',
  `goods_cart_count` int(11) NOT NULL DEFAULT 0 COMMENT '加购件数',
  `goods_order_count` decimal(12,3) NOT NULL DEFAULT 0.000 COMMENT '下单件数',
  `order_create_money` decimal(10,2) NOT NULL DEFAULT 0.00 COMMENT '订单下单总额',
  `order_create_count` int(11) NOT NULL DEFAULT 0 COMMENT '订单下单量',
  `balance_deduction` decimal(10,2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '余额抵扣总额',
  `cashier_billing_count` int(11) NOT NULL DEFAULT 0 COMMENT '开单数量',
  `cashier_billing_money` decimal(10,2) NOT NULL DEFAULT 0.00 COMMENT '开单金额',
  `cashier_buycard_count` int(11) NOT NULL DEFAULT 0 COMMENT '办卡数量',
  `cashier_buycard_money` decimal(10,2) NOT NULL DEFAULT 0.00 COMMENT '办卡金额',
  `cashier_recharge_count` int(11) NOT NULL DEFAULT 0 COMMENT '收银台充值数量',
  `cashier_recharge_money` decimal(10,2) NOT NULL DEFAULT 0.00 COMMENT '收银台充值金额',
  `cashier_refund_count` int(11) NOT NULL DEFAULT 0 COMMENT '收银台退款数量',
  `cashier_refund_money` decimal(10,2) NOT NULL DEFAULT 0.00 COMMENT '收银台退款金额',
  `cashier_order_member_count` int(11) NOT NULL DEFAULT 0 COMMENT '收银台下单会员数',
  `cashier_balance_money` decimal(10,2) NOT NULL DEFAULT 0.00 COMMENT '收银台余额消费金额',
  `cashier_online_pay_money` decimal(10,2) NOT NULL DEFAULT 0.00 COMMENT '收银台线上金额',
  `cashier_online_refund_money` decimal(10,2) NOT NULL DEFAULT 0.00 COMMENT '收银台线上退款金额',
  `cashier_balance_deduction` decimal(10,2) NOT NULL DEFAULT 0.00 COMMENT '门店余额总计'
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_general_ci;

