  `to_verify_time` int(11) NOT NULL DEFAULT 0 COMMENT '确认待审时间',
  `verify_time` int(11) NOT NULL DEFAULT 0 COMMENT '审核时间',
  `refuse_reason` varchar(255) NOT NULL DEFAULT '' COMMENT '拒绝理由'
