--
-- 表的结构 `ns_store`
--

CREATE TABLE `ns_store` (
  `store_id` int(11) NOT NULL COMMENT '门店站点id',
  `store_name` varchar(50) NOT NULL DEFAULT '' COMMENT '门店名称',
  `telphone` varchar(255) NOT NULL DEFAULT '' COMMENT '联系电话',
  `store_image` varchar(255) NOT NULL DEFAULT '' COMMENT '门店图片',
  `site_id` int(11) NOT NULL DEFAULT 0 COMMENT '商家id',
  `site_name` varchar(255) NOT NULL DEFAULT '' COMMENT '站点名称',
  `status` int(11) NOT NULL DEFAULT 0 COMMENT '状态',
  `province_id` int(11) NOT NULL DEFAULT 0 COMMENT '省id',
  `city_id` int(11) NOT NULL DEFAULT 0 COMMENT '市id',
  `district_id` int(11) NOT NULL DEFAULT 0 COMMENT '区县id',
  `community_id` int(11) NOT NULL DEFAULT 0 COMMENT '社区id',
  `address` varchar(255) NOT NULL DEFAULT '' COMMENT '地址',
  `full_address` varchar(255) NOT NULL DEFAULT '' COMMENT '详细地址',
  `longitude` varchar(50) NOT NULL DEFAULT '' COMMENT '经度',
  `latitude` varchar(50) NOT NULL DEFAULT '' COMMENT '纬度',
  `is_pickup` tinyint(4) NOT NULL DEFAULT 0 COMMENT '是否启用自提',
  `is_o2o` tinyint(4) NOT NULL DEFAULT 0 COMMENT '是否启用本地配送',
  `open_date` varchar(1000) NOT NULL DEFAULT '' COMMENT '营业时间',
  `o2o_fee_json` varchar(1000) NOT NULL DEFAULT '' COMMENT '配送费用设置',
  `create_time` int(11) NOT NULL DEFAULT 0 COMMENT '创建时间',
  `modify_time` int(11) NOT NULL DEFAULT 0 COMMENT '修改时间',
  `username` varchar(255) NOT NULL DEFAULT '' COMMENT '门店管理员',
  `order_money` decimal(10,2) NOT NULL DEFAULT 0.00 COMMENT '付款后订单金额',
  `order_complete_money` decimal(10,2) NOT NULL DEFAULT 0.00 COMMENT '订单完成-订单金额',
  `order_num` int(11) NOT NULL DEFAULT 0 COMMENT '订单数',
  `order_complete_num` int(11) NOT NULL DEFAULT 0 COMMENT '订单完成数量',
  `is_frozen` tinyint(4) NOT NULL DEFAULT 0 COMMENT '是否冻结0-未冻结 1已冻结',
  `uid` int(11) DEFAULT 0 COMMENT '门店管理员id',
  `time_type` int(11) NOT NULL DEFAULT 0 COMMENT '时间选取类型 0 每天  1 自定义',
  `time_week` varchar(255) NOT NULL DEFAULT '' COMMENT '营业时间  周一 周二.......',
  `start_time` int(11) NOT NULL DEFAULT 0 COMMENT '当日的起始时间',
  `end_time` int(11) NOT NULL DEFAULT 0 COMMENT '当日的营业结束时间',
  `stock_type` varchar(255) NOT NULL DEFAULT 'all' COMMENT '库存设置 store-门店独立库存 all总部统一库存',
  `is_default` int(11) NOT NULL DEFAULT 0 COMMENT '是否是默认门店',
  `store_type` varchar(255) NOT NULL DEFAULT 'directsale' COMMENT '门店类型',
  `time_interval` int(11) NOT NULL DEFAULT 30 COMMENT '时段设置单位分钟',
  `delivery_time` varchar(2000) NOT NULL DEFAULT '' COMMENT '配送时间段',
  `advance_day` int(11) NOT NULL DEFAULT 0 COMMENT '时间选择需提前多少天',
  `most_day` int(11) NOT NULL DEFAULT 7 COMMENT '最多可预约多少天',
  `account` decimal(10,2) NOT NULL DEFAULT 0.00 COMMENT '当前账户余额',
  `account_apply` decimal(10,2) NOT NULL DEFAULT 0.00 COMMENT '转账申请中金额',
  `account_withdraw` decimal(10,2) NOT NULL DEFAULT 0.00 COMMENT '已结算转账金额',
  `is_settlement` tinyint(4) NOT NULL DEFAULT 0 COMMENT '是否需要结算',
  `settlement_rate` decimal(10,2) NOT NULL DEFAULT 0.00 COMMENT '开启结算0代表跟随系统，不为零表示独立设置',
  `bank_type` tinyint(4) NOT NULL DEFAULT 1 COMMENT '银行账户类型',
  `bank_type_name` varchar(255) NOT NULL DEFAULT '' COMMENT '账户名称',
  `bank_user_name` varchar(255) NOT NULL DEFAULT '' COMMENT '账户所属人',
  `bank_type_account` varchar(255) NOT NULL DEFAULT '' COMMENT '账户类型对应账号',
  `category_id` int(11) NOT NULL DEFAULT 0 COMMENT '门店分类id',
  `category_name` varchar(255) NOT NULL DEFAULT '' COMMENT '门店分类名称',
  `label_id` varchar(255) NOT NULL DEFAULT '' COMMENT '门店标签,id,id,',
  `label_name` varchar(5000) NOT NULL DEFAULT '' COMMENT '门店标签,name,name,',
  `is_express` int(11) NOT NULL DEFAULT 0 COMMENT '是否启用快递配送',
  `store_images` text DEFAULT NULL COMMENT '门店图片多图',
  `store_introduce` longtext DEFAULT NULL COMMENT '门店介绍',
  `open_date_config` varchar(1000) NOT NULL DEFAULT '[]' COMMENT '营业时间配置 json格式',
  `out_open_date_o2o_pay` tinyint(1) NOT NULL DEFAULT 1 COMMENT '非营业时间能否下同城配送单 1：能 0：不能',
  `close_show` tinyint(1) NOT NULL DEFAULT 0 COMMENT '门店休息是否前台展示',
  `close_desc` varchar(255) DEFAULT '' COMMENT '门店休息说明'
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_general_ci COMMENT='线下门店表';

--
-- 转存表中的数据 `ns_store`
