--
-- 表的结构 `ns_v3_upgrade_log`
--

CREATE TABLE `ns_v3_upgrade_log` (
  `id` int(11) UNSIGNED NOT NULL,
  `module` varchar(255) NOT NULL DEFAULT '' COMMENT '模块标识',
  `title` varchar(255) NOT NULL DEFAULT '' COMMENT '模块名称',
  `create_time` int(11) NOT NULL DEFAULT 0 COMMENT '迁移时间',
  `remark` varchar(255) NOT NULL DEFAULT '' COMMENT '备注',
  `status` int(11) NOT NULL DEFAULT 0 COMMENT '迁移完成状态 1：完成 0 ：未完成'
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_general_ci COMMENT='v3Tov4迁移数据日志';

-- --------------------------------------------------------

--
-- 表的结构 `ns_verifier`
--

CREATE TABLE `ns_verifier` (
  `verifier_id` int(11) UNSIGNED NOT NULL COMMENT '核销员id',
  `verifier_name` varchar(255) NOT NULL DEFAULT '' COMMENT '核销员姓名',
  `site_id` int(11) NOT NULL DEFAULT 0 COMMENT '商家id',
  `member_id` int(11) NOT NULL DEFAULT 0 COMMENT '前台会员id',
  `uid` int(11) NOT NULL DEFAULT 0 COMMENT '后台用户id',
  `verifier_type` tinyint(4) NOT NULL DEFAULT 0 COMMENT '核销员类型：0平台核销员，1门店核销员',
  `store_id` int(11) NOT NULL DEFAULT 0 COMMENT '门店id',
  `create_time` int(11) NOT NULL DEFAULT 0 COMMENT '创建时间',
  `modify_time` int(11) NOT NULL DEFAULT 0 COMMENT '修改时间'
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_general_ci COMMENT='核销员（商品或订单商品）';

-- --------------------------------------------------------

--
-- 表的结构 `ns_verify`
--

CREATE TABLE `ns_verify` (
  `id` int(11) UNSIGNED NOT NULL COMMENT '主键',
  `site_id` int(11) NOT NULL DEFAULT 0 COMMENT '站点id',
  `site_name` varchar(255) NOT NULL DEFAULT '' COMMENT '站点名称',
  `verify_code` varchar(255) NOT NULL DEFAULT '' COMMENT '核销码',
  `verify_type` varchar(255) NOT NULL DEFAULT '' COMMENT '核销类型',
  `verify_type_name` varchar(255) NOT NULL DEFAULT '' COMMENT '核销类型名称',
  `verify_content_json` varchar(5000) NOT NULL DEFAULT '' COMMENT '核销相关数据',
  `verifier_id` int(11) NOT NULL DEFAULT 0 COMMENT '核销员id',
  `verifier_name` varchar(255) NOT NULL DEFAULT '' COMMENT '核销员姓名',
  `is_verify` int(11) NOT NULL DEFAULT 0 COMMENT '是否已经核销',
  `create_time` int(11) NOT NULL DEFAULT 0 COMMENT '创建时间',
  `verify_time` int(11) NOT NULL DEFAULT 0 COMMENT '核销时间',
  `expire_time` int(11) NOT NULL DEFAULT 0 COMMENT '核销有效期 0永久',
  `verify_from` varchar(20) NOT NULL DEFAULT 'mobile' COMMENT '核销来源 shop 商家后台 store 门店后台 mobile 手机端',
  `verify_remark` varchar(50) NOT NULL DEFAULT '' COMMENT '核销备注',
  `verify_total_count` int(11) NOT NULL DEFAULT 0 COMMENT '核销次数 0为不限核销次数',
  `verify_use_num` int(11) NOT NULL DEFAULT 0 COMMENT '已核销次数',
  `store_id` int(11) NOT NULL DEFAULT 0 COMMENT '所属门店 0为全部门店可核销',
  `member_id` int(11) NOT NULL DEFAULT 0 COMMENT '会员id'
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_general_ci COMMENT='核销编码管理';

