--
-- 表的结构 `ns_weapp`
--

CREATE TABLE `ns_weapp` (
  `weapp_id` int(11) UNSIGNED NOT NULL COMMENT '小程序ID',
  `site_id` int(11) NOT NULL DEFAULT 0 COMMENT '站点ID',
  `weapp_name` varchar(100) NOT NULL DEFAULT '' COMMENT '小程序名称',
  `appid` varchar(100) NOT NULL DEFAULT '' COMMENT '小程序AppID',
  `appsecret` varchar(255) NOT NULL DEFAULT '' COMMENT '小程序密钥',
  `weapp_original` varchar(100) NOT NULL DEFAULT '' COMMENT '小程序原始ID',
  `qrcode` varchar(255) NOT NULL DEFAULT '' COMMENT '小程序二维码',
  `status` tinyint(1) NOT NULL DEFAULT 1 COMMENT '状态：1启用，0禁用',
  `is_default` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否默认小程序：1是，0否',
  `token` varchar(100) NOT NULL DEFAULT 'TOKEN' COMMENT 'Token',
  `encodingaeskey` varchar(255) NOT NULL DEFAULT '' COMMENT 'EncodingAESKey',
  `create_time` int(11) NOT NULL DEFAULT 0 COMMENT '创建时间',
  `modify_time` int(11) NOT NULL DEFAULT 0 COMMENT '修改时间'
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_general_ci COMMENT='小程序管理表';

