--
-- 表的结构 `ns_weapp_experiencer`
--

CREATE TABLE `ns_weapp_experiencer` (
  `id` int(11) NOT NULL,
  `site_id` int(11) NOT NULL DEFAULT 0 COMMENT '站点id',
  `wechatid` varchar(255) NOT NULL DEFAULT '' COMMENT '微信号',
  `userstr` varchar(255) NOT NULL DEFAULT '' COMMENT '微信用户唯一值',
  `create_time` int(11) NOT NULL DEFAULT 0 COMMENT '添加时间'
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_general_ci COMMENT='微信小程序体验者';

